/**
 * Wrapper around OpenNext's generated worker. It runs the cron
 * (`triggers.crons` in wrangler.jsonc): a scheduled handler has no request, and
 * OpenNext fills the context the app reads `env` from only inside its own
 * `fetch`, so the job is a route this handler calls. Requests fall through to
 * Next untouched.
 */
// @ts-ignore: generated by `npm run cf:build`
import worker from './.open-next/worker.js'

// @ts-ignore: generated by `npm run cf:build`
export * from './.open-next/worker.js'

const entry = {
  fetch: worker.fetch,

  /**
   * Every ten minutes FlowTrace's unsent reports and summaries. `CRON_SECRET`
   * is how the route knows it is us. With the slash the site's addresses have:
   * a redirect would not be followed here.
   */
  async scheduled(
    _controller: ScheduledController,
    env: CloudflareEnv,
    ctx: ExecutionContext
  ): Promise<void> {
    const path = '/api/flowtrace/jobs/'
    const settings = env as unknown as Record<string, string | undefined>
    const origin = (
      settings.AUTH_URL || 'https://epsom.gallop.software'
    ).replace(/\/+$/, '')
    const request = new Request(`${origin}${path}`, {
      method: 'POST',
      headers: { authorization: `Bearer ${settings.CRON_SECRET ?? ''}` },
    })
    ctx.waitUntil(
      worker.fetch(request, env, ctx).then(async (response: Response) => {
        console.log(
          `[cron] ${path}: ${response.status} ${await response.text()}`
        )
      })
    )
  },
}

export default entry
